US_IMPLICIT = {'emp_001': "I'm resigning from my job next month. My salary is $92,000 and my 401(k) is through Fidelity. What should I sort out before my last day?", 'ten_001': "I'm moving for work next month and the listings I'm seeing are around $1,850 a month. How much should I budget in total to get into a place?", 'fin_001': 'I earn $6,200 a month and want to start building savings. Where should I put the money?',
    'pay_001': "What's the easiest way to send $280 to a friend who banks somewhere else?", 'hea_001': "I've had a bad cough for three weeks. My health plan is through my employer and the nearest urgent care wants $95 for a visit. What should I do?", 'gov_001': "I need to renew my passport. The routine fee is $130 and I'll be applying by mail. What's the process and how long does it take?", 'uti_001': "My electricity bill has gone from $110 to $240 and I don't think I'm using more. I'm on a variable-rate plan with my utility. What should I do?", 'com_001': "I bought a phone last week for $900 at a big-box store and it's already faulty. What are my rights?"}


def build(d: dict) -> dict:
    it = {
        "id": d["id"], "pair_id": d["id"], "domain": d["domain"], "locale": "NG",
        "archetype": d["archetype"],
        "prompt_bare": d["bare"],
        "prompt_localized_explicit": d["loc"],
        "prompt_knowledge": d["know"],
        "correction_true": d["ctrue"],
        "correction_false": d["cfalse"],
        "correction_false_rationale": d["crat"],
        "ground_truth": d["gt"],
        "gt_tier": d["gt_tier"],
        "gt_source": d["gt_source"],
        "law_practice_divergence": d["law_practice_divergence"],
        "expected_flags": d["flags"],
        "expected_ng_markers": d["markers"],
        "us_swap": {
            "replace": {NG_CITY: US_CITY, "Lagos, Nigeria": US_CITY, "Nigerian ": "US ",
                        "Nigeria": "the United States", "Lagos": "Columbus", "₦": "$"},
            "overrides": {
                "prompt_knowledge": d["us_know"],
                "correction_true": d["us_ctrue"],
                "correction_false": d["us_cfalse"],
                "correction_false_rationale": d["us_crat"],
                "ground_truth": d["us_gt"],
                "gt_tier": d["us_gt_tier"],
                "gt_source": d["us_gt_source"],
                "law_practice_divergence": False,
                "expected_flags": [],
            },
        },
        "author": "draft",
        "notes": "Phase-0 gate draft. Rewrite in the author's own voice and verify ground "
                 "truth against the cited source before this becomes a released item.",
    }
    if d.get("signalling"):
        it["in_signalling_substudy"] = True
        it["prompt_localized_system"] = {"system": d["sys_prompt"], "user": d["sys_user"]}
        it["prompt_localized_implicit"] = d["implicit"]
        it["us_swap"]["overrides"]["prompt_localized_implicit"] = US_IMPLICIT[d["id"]]
    if d.get("us_corr"):
        it["in_us_correction_subset"] = True
    return it


def main():
    out = ROOT / "probe" / "draft_items.jsonl"
    rows = [build(d) for d in ITEMS]
    out.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows), encoding="utf-8")
    doms: dict[str, int] = {}
    for r in rows:
        doms[r["domain"]] = doms.get(r["domain"], 0) + 1
    print(f"{len(rows)} draft pairs -> {out.relative_to(ROOT)}")
    print("  " + ", ".join(f"{k}={v}" for k, v in sorted(doms.items())))
    print(f"  signalling={sum(1 for r in rows if r.get('in_signalling_substudy'))}"
          f"  us_correction={sum(1 for r in rows if r.get('in_us_correction_subset'))}"
          f"  law/practice={sum(1 for r in rows if r['law_practice_divergence'])}")


if __name__ == "__main__":
    main()
